-- Lesson L0003: Look-alike words, different melodies (words).
-- Generated by approved-scripts/db_sql.py lesson (called by lesson_tool.py merge) from data/*.csv.
-- Do not edit by hand; regenerate instead. Upserts change only rows that differ; it applies on an
-- empty DB as well. Rows: 4 words, 2 sentences, 5 sentence_words, 1 lessons, 6 lesson_items.

on conflict (word_id) do update set lao = excluded.lao, ipa = excluded.ipa, respelling = excluded.respelling, syllables = excluded.syllables, tone_by_syllable = excluded.tone_by_syllable, tone_derivation = excluded.tone_derivation, pos = excluded.pos, classifier_word_id = excluded.classifier_word_id, classifier_type = excluded.classifier_type, classifier_confidence = excluded.classifier_confidence, component_word_ids = excluded.component_word_ids, gloss_en = excluded.gloss_en, freq_rank = excluded.freq_rank, topic = excluded.topic, tier = excluded.tier, intro_order = excluded.intro_order, new_letter_ids = excluded.new_letter_ids, new_vowel_ids = excluded.new_vowel_ids, pron_tip = excluded.pron_tip, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.lao, t.ipa, t.respelling, t.syllables, t.tone_by_syllable, t.tone_derivation, t.pos, t.classifier_word_id, t.classifier_type, t.classifier_confidence, t.component_word_ids, t.gloss_en, t.freq_rank, t.topic, t.tier, t.intro_order, t.new_letter_ids, t.new_vowel_ids, t.pron_tip, t.source, t.confidence, t.notes) is distinct from (excluded.lao, excluded.ipa, excluded.respelling, excluded.syllables, excluded.tone_by_syllable, excluded.tone_derivation, excluded.pos, excluded.classifier_word_id, excluded.classifier_type, excluded.classifier_confidence, excluded.component_word_ids, excluded.gloss_en, excluded.freq_rank, excluded.topic, excluded.tier, excluded.intro_order, excluded.new_letter_ids, excluded.new_vowel_ids, excluded.pron_tip, excluded.source, excluded.confidence, excluded.notes));
on conflict (sentence_id) do update set lao = excluded.lao, lao_spaced = excluded.lao_spaced, ipa = excluded.ipa, respelling = excluded.respelling, english = excluded.english, target_word_id = excluded.target_word_id, template_id = excluded.template_id, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, word_overrides = excluded.word_overrides, retired_at = null
where (t.retired_at is not null or (t.lao, t.lao_spaced, t.ipa, t.respelling, t.english, t.target_word_id, t.template_id, t.source, t.confidence, t.notes, t.word_overrides) is distinct from (excluded.lao, excluded.lao_spaced, excluded.ipa, excluded.respelling, excluded.english, excluded.target_word_id, excluded.template_id, excluded.source, excluded.confidence, excluded.notes, excluded.word_overrides));
on conflict (sentence_id, position) do update set word_id = excluded.word_id, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.word_id, t.source, t.confidence, t.notes) is distinct from (excluded.word_id, excluded.source, excluded.confidence, excluded.notes));
update public.sentence_words t set retired_at = now()
where t.retired_at is null and t.sentence_id in ('S000002870', 'S000002871') and (t.sentence_id, t.position) not in (('S000002870', 1), ('S000002870', 2), ('S000002871', 1), ('S000002871', 2), ('S000002871', 3));
on conflict (lesson_id) do update set lesson_order = excluded.lesson_order, title_en = excluded.title_en, kind = excluded.kind, summary_en = excluded.summary_en, source = excluded.source, confidence = excluded.confidence, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.lesson_order, t.title_en, t.kind, t.summary_en, t.source, t.confidence, t.notes) is distinct from (excluded.lesson_order, excluded.title_en, excluded.kind, excluded.summary_en, excluded.source, excluded.confidence, excluded.notes));
on conflict (lesson_id, position) do update set item_type = excluded.item_type, item_id = excluded.item_id, role = excluded.role, notes = excluded.notes, retired_at = null
where (t.retired_at is not null or (t.item_type, t.item_id, t.role, t.notes) is distinct from (excluded.item_type, excluded.item_id, excluded.role, excluded.notes));
update public.lesson_items t set retired_at = now()
where t.retired_at is null and t.lesson_id in ('L0003') and (t.lesson_id, t.position) not in (('L0003', 1), ('L0003', 2), ('L0003', 3), ('L0003', 4), ('L0003', 5), ('L0003', 6));
